mapper.select:
SELECT CAPFI.*, ROUND(CAPFI.FEE_AMOUNT*EXCHANGE_RATE,2) CNY_FEE_AMOUNT, nvl(PJ.ORGANIZATION_NAME,PD.ORGANIZATION_NAME) ORGANIZATION_NAME, nvl(PJ.ORGANIZATION_NAME, PD.ORGANIZATION_NAME) ORGANIZATION_ID_N, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = CAPFI.FEE_NAME and s.code = 'BI.COST_NAME') as FEE_NAME_N, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = CAPFI.CALCULATE_FLAG and s.code = 'SYS.YES_NO') as CALCULATE_FLAG_N, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = CAPFI.CURRENCY_CODE and s.code = 'CHS.CURRENCY_TYPE') as CURRENCY_CODE_N, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = CAPFI.SHARE_TYPE and s.code = 'BI.COST_SHARING_TYPE') as SHARE_TYPE_N, (select s.MEANING from sys_code_value_b_v s where s.CODE_VALUE = CAPFI.ADD_TAX_RATE and s.code = 'ABS.ADD_TAX_RATE') as ADD_TAX_RATE_N FROM CT_ABS_PRO_FEE_INFO CAPFI LEFT JOIN CT_ABS_PROJECT_ORGANIZATION PJ ON CAPFI.ORGANIZATION_ID=PJ.ORGANIZATION_ID -- AND CAPFI.SOURCE_TYPE='ABS_PROJECT' LEFT JOIN CT_ABS_PRODUCT_ORGANIZATION PD ON CAPFI.ORGANIZATION_ID=PD.ORGANIZATION_ID -- AND CAPFI.SOURCE_TYPE='ABS_PRODUCT' WHERE 1=1
AND CAPFI.SOURCE_KEY = #{sourceKey}
AND CAPFI.SOURCE_TYPE = #{sourceType}
AND CAPFI.CALCULATE_FLAG = #{calculateFlag}
ORDER BY CAPFI.ORGANIZATION_ID,CAPFI.FEE_NAME,CAPFI.EXCHANGE_RATE

mapper.update:
UPDATE
    CT_ABS_PRO_FEE_INFO CAPFI
  SET
     CAPFI.ORGANIZATION_ID=#{targetOrganizationId}
  WHERE
     CAPFI.SOURCE_TYPE='ABS_PRODUCT'
   AND CAPFI.SOURCE_KEY=#{productId}
   AND CAPFI.ORGANIZATION_ID=#{sourceOrganizationId}
